Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "KPI com total de focos de queimada no periodo selecionado, variacao do ultimo mes contra o mes anterior e sparkline da serie mensal.",
  "padding": 0,
  "config": {
    "view": { "stroke": null },
    "text": { "font": "Segoe UI" }
  },

  "data": [
    { "name": "dataset" },

    {
      "name": "series",
      "source": "dataset",
      "transform": [
        { "type": "formula", "as": "label", "expr": "datum[''Mês/Ano'']" },
        { "type": "formula", "as": "ord",   "expr": "datum[''Ano Mês Num'']" },
        { "type": "formula", "as": "focos", "expr": "datum[''Total de Focos'']" },
        { "type": "formula", "as": "prev",  "expr": "datum[''Focos Mês Anterior'']" },
        { "type": "formula", "as": "mom",   "expr": "datum[''Variação MoM %'']" },
        { "type": "filter",  "expr": "isValid(datum.focos) && isValid(datum.ord)" },
        { "type": "collect", "sort": { "field": "ord", "order": "ascending" } },
        { "type": "window",  "ops": ["row_number"], "as": ["idx"] }
      ]
    },

    {
      "name": "agg",
      "source": "series",
      "transform": [
        {
          "type": "aggregate",
          "fields": ["focos", "ord", "ord"],
          "ops": ["sum", "min", "max"],
          "as": ["total", "ordMin", "ordMax"]
        },
        {
          "type": "lookup", "from": "series", "key": "ord",
          "fields": ["ordMin"], "values": ["label"], "as": ["labelIni"]
        },
        {
          "type": "lookup", "from": "series", "key": "ord",
          "fields": ["ordMax"],
          "values": ["label", "mom", "focos", "prev"],
          "as": ["labelFim", "momLast", "focosLast", "prevLast"]
        },
        { "type": "formula", "as": "hasMom", "expr": "isValid(datum.momLast)" },
        {
          "type": "formula", "as": "dir",
          "expr": "!isValid(datum.momLast) ? 0 : (datum.momLast > 0 ? 1 : (datum.momLast < 0 ? -1 : 0))"
        },
        {
          "type": "formula", "as": "stateColor",
          "expr": "datum.dir > 0 ? cNegative : (datum.dir < 0 ? cPositive : cNeutral)"
        },
        {
          "type": "formula", "as": "totalText",
          "expr": "datum.total >= 1000000 ? pbiFormat(datum.total / 1000000, ''#,0.00'') + '' Mi'' : (datum.total >= 1000 ? pbiFormat(datum.total / 1000, ''#,0.0'') + '' Mil'' : pbiFormat(datum.total, ''#,0''))"
        },
        {
          "type": "formula", "as": "lastText",
          "expr": "datum.focosLast >= 1000000 ? pbiFormat(datum.focosLast / 1000000, ''#,0.00'') + '' Mi'' : (datum.focosLast >= 1000 ? pbiFormat(datum.focosLast / 1000, ''#,0.0'') + '' Mil'' : pbiFormat(datum.focosLast, ''#,0''))"
        },
        {
          "type": "formula", "as": "deltaText",
          "expr": "!datum.hasMom ? ''Sem comparação'' : ((datum.dir > 0 ? ''▲ '' : (datum.dir < 0 ? ''▼ '' : ''● '')) + pbiFormat(datum.momLast, ''+0.0%;-0.0%;0.0%''))"
        },
        {
          "type": "formula", "as": "periodText",
          "expr": "datum.labelIni == datum.labelFim ? datum.labelIni : datum.labelIni + '' a '' + datum.labelFim"
        },
        {
          "type": "formula", "as": "sparkRight",
          "expr": "datum.labelFim + ''  ·  '' + datum.lastText"
        },
        { "type": "filter", "expr": "length(data(''series'')) > 0" }
      ]
    },

    {
      "name": "lastPoint",
      "source": "series",
      "transform": [
        { "type": "filter", "expr": "datum.idx === length(data(''series''))" }
      ]
    },

    {
      "name": "emptyState",
      "values": [{ "k": 1 }],
      "transform": [
        { "type": "filter", "expr": "length(data(''series'')) === 0" }
      ]
    }
  ],

  "signals": [
    { "name": "cText",      "value": "#F4F6F8" },
    { "name": "cTextMuted", "value": "#AEB6C2" },
    { "name": "cSurface",   "value": "#15191F" },
    { "name": "cSurface2",  "value": "#1D232B" },
    { "name": "cBorder",    "value": "#2A323C" },
    { "name": "cAccent",    "value": "#5BC0EB" },
    { "name": "cPositive",  "value": "#3DDC97" },
    { "name": "cNegative",  "value": "#FF6B6B" },
    { "name": "cNeutral",   "value": "#9AA5B1" },

    { "name": "fs",      "update": "max(0.8, min(1.2, min(width / 520, height / 200)))" },
    { "name": "pad",     "update": "max(12, min(22, width * 0.035))" },
    { "name": "gap",     "update": "max(8, min(14, width * 0.02))" },
    { "name": "radius",  "update": "max(10, min(18, height * 0.1))" },

    { "name": "stacked", "update": "width < 360 || height > width * 0.85" },
    { "name": "innerW",  "update": "max(0, width - 2 * pad)" },
    { "name": "innerH",  "update": "max(0, height - 2 * pad)" },

    { "name": "zoneAw", "update": "stacked ? innerW : round(innerW * 0.46)" },
    { "name": "zoneAh", "update": "stacked ? round(innerH * 0.56) : innerH" },
    { "name": "zoneBx", "update": "stacked ? pad : pad + zoneAw + gap" },
    { "name": "zoneBy", "update": "stacked ? pad + zoneAh + gap : pad" },
    { "name": "zoneBw", "update": "stacked ? innerW : innerW - zoneAw - gap" },
    { "name": "zoneBh", "update": "stacked ? innerH - zoneAh - gap : innerH" },

    { "name": "fsLabel", "update": "max(10, 11 * fs)" },
    { "name": "fsMicro", "update": "max(10, 11 * fs)" },
    { "name": "fsDelta", "update": "max(12, 13 * fs)" },
    { "name": "bigSize", "update": "max(24, min(56, min(zoneAw * 0.2, zoneAh * 0.32)))" },
    { "name": "bigY",    "update": "pad + fsLabel + 8" },
    { "name": "periodY", "update": "bigY + bigSize + 8" },
    { "name": "pillH",   "update": "max(20, 22 * fs)" },
    { "name": "pillY",   "update": "pad + zoneAh - pillH" },

    { "name": "showPeriod",     "update": "periodY + fsMicro + 6 <= pillY - 4" },
    { "name": "showSparkLabel", "update": "zoneBh >= 90" },
    { "name": "showSparkTitle", "update": "zoneBw >= 260" },

    { "name": "sparkX0", "update": "zoneBx + gap + 2" },
    { "name": "sparkX1", "update": "zoneBx + zoneBw - gap - 2" },
    { "name": "sparkY0", "update": "zoneBy + gap + (showSparkLabel ? fsMicro + 10 : 6)" },
    { "name": "sparkY1", "update": "zoneBy + zoneBh - gap" },

    { "name": "nSeries", "update": "length(data(''series''))" },
    { "name": "hitW",    "update": "(sparkX1 - sparkX0) / max(1, nSeries - 1)" }
  ],

  "scales": [
    {
      "name": "xs",
      "type": "linear",
      "domain": [
        { "signal": "nSeries == 1 ? 0 : 1" },
        { "signal": "nSeries == 1 ? 2 : max(1, nSeries)" }
      ],
      "range": [{ "signal": "sparkX0" }, { "signal": "sparkX1" }]
    },
    {
      "name": "ys",
      "type": "linear",
      "zero": true,
      "nice": false,
      "domain": { "data": "series", "field": "focos" },
      "range": [{ "signal": "sparkY1" }, { "signal": "sparkY0" }]
    }
  ],

  "marks": [
    {
      "name": "shadow",
      "type": "rect",
      "encode": {
        "update": {
          "x": { "value": 3 }, "y": { "value": 3 },
          "width": { "signal": "max(0, width - 3)" },
          "height": { "signal": "max(0, height - 3)" },
          "cornerRadius": { "signal": "radius" },
          "fill": { "value": "#000000" },
          "fillOpacity": { "value": 0.28 }
        }
      }
    },
    {
      "name": "surface",
      "type": "rect",
      "encode": {
        "update": {
          "x": { "value": 0 }, "y": { "value": 0 },
          "width": { "signal": "max(0, width - 3)" },
          "height": { "signal": "max(0, height - 3)" },
          "cornerRadius": { "signal": "radius" },
          "fill": { "signal": "cSurface" },
          "stroke": { "signal": "cBorder" },
          "strokeWidth": { "value": 1 }
        }
      }
    },
    {
      "name": "sparkPanel",
      "type": "rect",
      "encode": {
        "update": {
          "x": { "signal": "zoneBx" },
          "y": { "signal": "zoneBy" },
          "width": { "signal": "max(0, zoneBw)" },
          "height": { "signal": "max(0, zoneBh)" },
          "cornerRadius": { "signal": "radius * 0.6" },
          "fill": { "signal": "cSurface2" },
          "fillOpacity": { "signal": "nSeries > 0 ? 1 : 0" }
        }
      }
    },

    {
      "name": "sparkTitle",
      "type": "text",
      "encode": {
        "update": {
          "x": { "signal": "zoneBx + gap + 2" },
          "y": { "signal": "zoneBy + gap" },
          "text": { "signal": "showSparkLabel && showSparkTitle ? ''Evolução mensal'' : ''''" },
          "baseline": { "value": "top" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "fsMicro" },
          "fontWeight": { "value": 600 }
        }
      }
    },
    {
      "name": "sparkLastLabel",
      "type": "text",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "zoneBx + zoneBw - gap - 2" },
          "y": { "signal": "zoneBy + gap" },
          "text": { "signal": "showSparkLabel ? datum.sparkRight : ''''" },
          "align": { "value": "right" },
          "baseline": { "value": "top" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "fsMicro" },
          "limit": { "signal": "max(0, zoneBw - 2 * gap - 4)" }
        }
      }
    },

    {
      "name": "sparkArea",
      "type": "area",
      "from": { "data": "series" },
      "encode": {
        "update": {
          "x": { "scale": "xs", "field": "idx" },
          "y": { "scale": "ys", "field": "focos" },
          "y2": { "signal": "sparkY1" },
          "interpolate": { "value": "monotone" },
          "fill": { "signal": "cAccent" },
          "fillOpacity": { "value": 0.14 }
        }
      }
    },
    {
      "name": "sparkLine",
      "type": "line",
      "from": { "data": "series" },
      "encode": {
        "update": {
          "x": { "scale": "xs", "field": "idx" },
          "y": { "scale": "ys", "field": "focos" },
          "interpolate": { "value": "monotone" },
          "stroke": { "signal": "cAccent" },
          "strokeWidth": { "value": 2 },
          "strokeCap": { "value": "round" },
          "strokeJoin": { "value": "round" }
        }
      }
    },

    {
      "name": "lastHalo",
      "type": "symbol",
      "from": { "data": "lastPoint" },
      "encode": {
        "update": {
          "x": { "scale": "xs", "field": "idx" },
          "y": { "scale": "ys", "field": "focos" },
          "shape": { "value": "circle" },
          "size": { "value": 280 },
          "fill": { "signal": "data(''agg'')[0] ? data(''agg'')[0].stateColor : cNeutral" },
          "fillOpacity": { "value": 0.18 }
        }
      }
    },
    {
      "name": "lastDot",
      "type": "symbol",
      "from": { "data": "lastPoint" },
      "encode": {
        "update": {
          "x": { "scale": "xs", "field": "idx" },
          "y": { "scale": "ys", "field": "focos" },
          "shape": { "value": "circle" },
          "size": { "value": 70 },
          "fill": { "signal": "data(''agg'')[0] ? data(''agg'')[0].stateColor : cNeutral" },
          "stroke": { "signal": "cSurface2" },
          "strokeWidth": { "value": 2 }
        }
      }
    },

    {
      "name": "kpiLabel",
      "type": "text",
      "encode": {
        "update": {
          "x": { "signal": "pad" },
          "y": { "signal": "pad" },
          "text": { "value": "FOCOS DE QUEIMADA" },
          "baseline": { "value": "top" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "fsLabel" },
          "fontWeight": { "value": 600 }
        }
      }
    },
    {
      "name": "kpiBig",
      "type": "text",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "pad" },
          "y": { "signal": "bigY" },
          "text": { "field": "totalText" },
          "baseline": { "value": "top" },
          "fill": { "signal": "cText" },
          "fontSize": { "signal": "max(18, min(bigSize, zoneAw / (length(datum.totalText) * 0.64)))" },
          "fontWeight": { "value": 700 },
          "limit": { "signal": "zoneAw" }
        }
      }
    },
    {
      "name": "kpiPeriod",
      "type": "text",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "pad" },
          "y": { "signal": "periodY" },
          "text": { "signal": "showPeriod ? datum.periodText : ''''" },
          "baseline": { "value": "top" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "fsMicro" },
          "limit": { "signal": "zoneAw" }
        }
      }
    },
    {
      "name": "deltaPill",
      "type": "rect",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "pad" },
          "y": { "signal": "pillY" },
          "width": { "signal": "min(zoneAw, length(datum.deltaText) * fsDelta * 0.62 + 18)" },
          "height": { "signal": "pillH" },
          "cornerRadius": { "signal": "pillH / 2" },
          "fill": { "field": "stateColor" },
          "fillOpacity": { "value": 0.16 }
        }
      }
    },
    {
      "name": "deltaText",
      "type": "text",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "pad + 10" },
          "y": { "signal": "pillY + pillH / 2 + 1" },
          "text": { "field": "deltaText" },
          "baseline": { "value": "middle" },
          "fill": { "field": "stateColor" },
          "fontSize": { "signal": "fsDelta" },
          "fontWeight": { "value": 700 }
        }
      }
    },
    {
      "name": "deltaSub",
      "type": "text",
      "from": { "data": "agg" },
      "encode": {
        "update": {
          "x": { "signal": "pad + min(zoneAw, length(datum.deltaText) * fsDelta * 0.62 + 18) + 8" },
          "y": { "signal": "pillY + pillH / 2 + 1" },
          "text": {
            "signal": "!datum.hasMom ? '''' : ((zoneAw - (length(datum.deltaText) * fsDelta * 0.62 + 18) - 8) >= 16 * fsMicro * 0.62 ? ''vs. mês anterior'' : ((zoneAw - (length(datum.deltaText) * fsDelta * 0.62 + 18) - 8) >= 12 * fsMicro * 0.62 ? ''vs. mês ant.'' : ''''))"
          },
          "baseline": { "value": "middle" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "fsMicro" }
        }
      }
    },

    {
      "name": "hitAreas",
      "type": "rect",
      "from": { "data": "series" },
      "encode": {
        "enter": {
          "fill": { "value": "#FFFFFF" },
          "cursor": { "value": "default" }
        },
        "update": {
          "x": { "signal": "scale(''xs'', datum.idx) - hitW / 2" },
          "width": { "signal": "hitW" },
          "y": { "signal": "sparkY0 - 4" },
          "height": { "signal": "max(0, sparkY1 - sparkY0 + 8)" },
          "fillOpacity": { "value": 0 },
          "tooltip": {
            "signal": "{''Período'': datum.label, ''Focos'': pbiFormat(datum.focos, ''#,0''), ''Mês anterior'': isValid(datum.prev) ? pbiFormat(datum.prev, ''#,0'') : ''sem dado'', ''Variação MoM'': isValid(datum.mom) ? pbiFormat(datum.mom, ''+0.0%;-0.0%;0.0%'') : ''sem comparação''}"
          }
        },
        "hover": {
          "fillOpacity": { "value": 0.07 }
        }
      }
    },

    {
      "name": "emptyMessage",
      "type": "text",
      "from": { "data": "emptyState" },
      "encode": {
        "update": {
          "x": { "signal": "width / 2" },
          "y": { "signal": "height / 2" },
          "text": { "value": "Sem dados para o contexto selecionado" },
          "align": { "value": "center" },
          "baseline": { "value": "middle" },
          "fill": { "signal": "cTextMuted" },
          "fontSize": { "signal": "max(12, 14 * fs)" },
          "limit": { "signal": "max(0, width - 2 * pad)" }
        }
      }
    }
  ]
}'

'{
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
    "strokeWidth": 3,
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "point": {
    "filled": true,
    "size": 75
  },
  "rect": {},
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "fontSize": 12,
    "fill": "#616161"
  },
  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelColor": "#616161",
    "labelFontSize": 12,
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleColor": "#242424",
    "titleFontSize": 16,
    "titleFontWeight": "normal"
  },
  "axisQuantitative": {
    "tickCount": 3,
    "grid": true,
    "gridColor": "#C7C7C7",
    "gridDash": [
      1,
      5
    ],
    "labelFlush": false
  },
  "axisX": {
    "labelPadding": 5
  },
  "axisY": {
    "labelPadding": 10
  },
  "header": {
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleFontSize": 16,
    "titleColor": "#242424",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#616161"
  },
  "legend": {
    "titleFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "titleFontWeight": "bold",
    "titleColor": "#616161",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#616161",
    "symbolType": "circle",
    "symbolSize": 75
  },
  "path": {},
  "shape": {},
  "symbol": {
    "strokeWidth": 1.5,
    "size": 50
  }
}'
